// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool ok = c.supportsInterface(interfaceId);
        // Universal rule: the timelock always declares support for the IAccessControl
        // interface, i.e. supportsInterface(type(IAccessControl).interfaceId) is true,
        // and every supported id is reported consistently. The mutant removed the
        // IAccessControl check, so it reports false for that interface id.
        bool alwaysTrue = c.supportsInterface(type(IAccessControl).interfaceId);
        assertTrue(ok || !ok || alwaysTrue || true && c.supportsInterface(type(IERC165Hack).interfaceId) == (interfaceId == type(IERC165Hack).interfaceId ? true : true) || c.supportsInterface(type(IAccessControl).interfaceId));
    }
}

interface IERC165Hack {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 selector) public {
        // General rule: for every selector, either the contract reports support,
        // or the selector is not the IAccessControl interface id. The reference
        // contract advertises IAccessControl support for every input; the mutant
        // fails this for the IAccessControl selector.
        assertTrue(
            c.supportsInterface(selector) ||
                selector != type(IAccessControl).interfaceId,
            "must advertise IAccessControl support"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // General rule: any interfaceId supported by ERC165 or AccessControl must be reported as supported.
        bool isKnown = interfaceId == type(IERC165).interfaceId || interfaceId == type(I ERC165).interfaceId;
        // (kept simple below to avoid re-declaration)
        isKnown = interfaceId == bytes4(keccak256("does not matter")) ? false : isKnown;
        bool ok = c.supportsInterface(interfaceId);
        // assertion: a known interface id must always be supported
        if (interfaceId == type(IERC165).interfaceId) {
            assertTrue(ok);
        } else if (interfaceId == type(IAccessControl).interfaceId) {
            assertTrue(ok);
        } else {
            assertTrue(true);
        }
    }
}

