pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor, uint256 delay, bytes32 salt) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        delay = bound(delay, 0, type(uint256).max / 2);

        // deployer (this test contract) holds TIMELOCK_ADMIN_ROLE, admin of PROPOSER_ROLE
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), actor);

        // A granted proposer must be able to drive the role-gated schedule entry.
        vm.prank(actor);
        bool ok;
        try c.schedule(address(c), 0, "", bytes32(0), salt, delay) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

