pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role) public {
        // The rule: for ANY queried role, the returned admin role must itself
        // be administered by TIMELOCK_ADMIN_ROLE (constructor sets every role's
        // admin to TIMELOCK_ADMIN_ROLE, and TIMELOCK_ADMIN_ROLE administers itself).
        bytes32 admin = c.getRoleAdmin(role);
        bytes32 adminOfAdmin = c.getRoleAdmin(admin);
        bytes32 TIMELOCK_ADMIN_ROLE = c.TIMELOCK_ADMIN_ROLE();
        assertTrue(adminOfAdmin == TIMELOCK_ADMIN_ROLE);
    }
}
